using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace RcsMap {
 public sealed class CorrectionBox:GroupBox {
  readonly MapDocument document;readonly Waypoint point;readonly ComboBox sources=new ComboBox();readonly ComboBox kind=new ComboBox();
  public readonly ListBox List=new ListBox();readonly Label summary=new Label();
  public CorrectionBox(MapDocument d,Waypoint p){document=d;point=p;Text="② 纠错模板（可空）";Dock=DockStyle.Fill;Padding=new Padding(8,25,8,8);
   var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5};root.RowStyles.Add(new RowStyle(SizeType.Absolute,34));root.RowStyles.Add(new RowStyle(SizeType.Absolute,34));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,104));root.RowStyles.Add(new RowStyle(SizeType.Absolute,90));Controls.Add(root);
   sources.Dock=kind.Dock=DockStyle.Fill;sources.DropDownStyle=kind.DropDownStyle=ComboBoxStyle.DropDownList;sources.DropDownWidth=470;sources.SelectedIndexChanged+=(s,e)=>RefreshKinds();root.Controls.Add(sources);RefreshKinds();root.Controls.Add(kind);List.Dock=DockStyle.Fill;List.HorizontalScrollbar=true;root.Controls.Add(List);List.DoubleClick+=(s,e)=>Edit();
   var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};root.Controls.Add(bar);Button(bar,"添加",Add);Button(bar,"编辑",Edit);Button(bar,"上移",()=>MoveTemplate(-1));Button(bar,"下移",()=>MoveTemplate(1));Button(bar,"删除",Remove);Button(bar,"定位硬件",()=>{using(var dialog=new HardwareDialog(document))dialog.ShowDialog(this);RefreshSources();});Button(bar,"到点参数",EditPointOptions);summary.Dock=DockStyle.Fill;summary.ForeColor=Color.SaddleBrown;root.Controls.Add(summary);RefreshSources();RefreshList();
  }
  static void Button(Control parent,string label,Action action){var b=new Button{Text=label,AutoSize=true,Height=29};b.Click+=(s,e)=>action();parent.Controls.Add(b);}
  public void RefreshSources(){sources.Items.Clear();foreach(var source in CorrectionRules.Sources(document))sources.Items.Add(source);if(sources.Items.Count>0)sources.SelectedIndex=0;summary.Text=sources.Items.Count==0?"未导入独立定位硬件：纠错留空。\r\n轮速闭环与反馈失联保护仍有效。":"导入仅提供模板，不自动添加。\r\n刷新只改估计；对齐会移动车辆。\r\n待接入源只能保存禁用模板。";if(point.CorrectionMode!=0)summary.Text+="\r\n旧自动纠错配置已停用。";}
  void RefreshKinds(){kind.Items.Clear();kind.Items.Add(CorrectionKind.刷新定位估计);var s=sources.SelectedItem as HardwareSource;if(s!=null&&(s.Axes&3)==3)kind.Items.Add(CorrectionKind.移动对齐XY);if(s!=null&&(s.Axes&4)==4)kind.Items.Add(CorrectionKind.原地对齐朝向);kind.SelectedIndex=0;}
  void EditPointOptions(){var copy=document.Clone();var shadow=copy.Points.First(p=>p.Id==point.Id);using(var dialog=new PropertyDialog("到点参数 · 旧自动纠错不执行",new PointOptions(shadow),()=>{if(!MapDocument.Finite(shadow.ArrivalRadius)||shadow.ArrivalRadius<1||shadow.ArrivalRadius>1000||!MapDocument.Finite(shadow.SettleMs)||shadow.SettleMs<1||shadow.SettleMs>10000||!MapDocument.Finite(shadow.DriftLimit)||shadow.DriftLimit<1||shadow.DriftLimit>1000)throw new Exception("到达半径/漂移须1～1000mm，停稳须1～10000ms。");})){if(dialog.ShowDialog(this)!=DialogResult.OK)return;}point.ArrivalRadius=shadow.ArrivalRadius;point.SettleMs=shadow.SettleMs;point.DriftLimit=shadow.DriftLimit;point.RunFinalDeparture=shadow.RunFinalDeparture;}
  public void Add(){var source=sources.SelectedItem as HardwareSource;if(source==null){MessageBox.Show(this,"没有独立定位源，保持空模板。请先导入并接入真实硬件档案。");return;}int behavior=(int)(CorrectionKind)kind.SelectedItem;var c=new CorrectionTemplate{SourceId=source.Id,Name=source.Name+"纠错",Kind=behavior,Axes=behavior==1?3:behavior==2?4:source.Axes,Enabled=source.Ready};if(!EditValue(c))return;if(point.Corrections==null)point.Corrections=new System.Collections.Generic.List<CorrectionTemplate>();point.Corrections.Add(c);document.Version=Math.Max(document.Version,5);RefreshList(point.Corrections.Count-1);}
  bool EditValue(CorrectionTemplate c){var shadow=new CorrectionTemplate();using(var stream=new MemoryStream()){var ser=new System.Runtime.Serialization.Json.DataContractJsonSerializer(typeof(CorrectionTemplate));ser.WriteObject(stream,c);stream.Position=0;shadow=(CorrectionTemplate)ser.ReadObject(stream);}using(var dialog=new PropertyDialog(c.Name,shadow,()=>{var copy=document.Clone();copy.Version=Math.Max(copy.Version,5);copy.Points.Clear();copy.Points.Add(new Waypoint{Corrections=new System.Collections.Generic.List<CorrectionTemplate>{shadow}});var errors=CorrectionRules.Validate(copy);if(errors.Count>0)throw new Exception(String.Join("\r\n",errors.ToArray()));})){if(dialog.ShowDialog(this)!=DialogResult.OK)return false;}foreach(var property in typeof(CorrectionTemplate).GetProperties().Where(x=>x.CanRead&&x.CanWrite))property.SetValue(c,property.GetValue(shadow,null),null);return true;}
  public void Edit(){int i=List.SelectedIndex;if(i<0)return;if(EditValue(point.Corrections[i]))RefreshList(i);}
  public void Remove(){int i=List.SelectedIndex;if(i<0)return;point.Corrections.RemoveAt(i);RefreshList(Math.Min(i,point.Corrections.Count-1));}
  public void MoveTemplate(int offset){int i=List.SelectedIndex,j=i+offset;if(i<0||j<0||j>=point.Corrections.Count)return;var item=point.Corrections[i];point.Corrections.RemoveAt(i);point.Corrections.Insert(j,item);RefreshList(j);}
  public void RefreshList(int selected=-1){List.Items.Clear();foreach(var c in CorrectionRules.Items(point))List.Items.Add(c);if(List.Items.Count>0)List.SelectedIndex=Math.Max(0,Math.Min(selected,List.Items.Count-1));}
 }
 public sealed class PropertyDialog:Form {
  public PropertyDialog(string title,object value,Action validate){Text=title;Size=new Size(560,620);MinimumSize=Size;StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);var grid=new PropertyGrid{SelectedObject=value,Dock=DockStyle.Fill,ToolbarVisible=false};Controls.Add(grid);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=42};var ok=new Button{Text="确定"};ok.Click+=(s,e)=>{try{grid.Focus();validate();DialogResult=DialogResult.OK;}catch(Exception error){MessageBox.Show(this,error.Message);}};bar.Controls.Add(ok);bar.Controls.Add(new Button{Text="取消",DialogResult=DialogResult.Cancel});Controls.Add(bar);}
 }
 public sealed class HardwareDialog:Form {
  readonly MapDocument document;readonly ListBox list=new ListBox();readonly PropertyGrid grid=new PropertyGrid();
  public HardwareDialog(MapDocument d){document=d;Text="定位硬件档案 · 导入不自动启用纠错";Size=new Size(1000,620);MinimumSize=new Size(860,570);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);var split=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,38));split.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,62));Controls.Add(split);list.Dock=grid.Dock=DockStyle.Fill;list.HorizontalScrollbar=true;grid.ToolbarVisible=false;grid.PropertySort=PropertySort.NoSort;split.Controls.Add(list,0,0);split.Controls.Add(grid,1,0);list.SelectedIndexChanged+=(s,e)=>grid.SelectedObject=list.SelectedItem;grid.PropertyValueChanged+=(s,e)=>{var descriptor=e.ChangedItem.PropertyDescriptor;try{document.StructuralCheck();}catch(Exception error){descriptor.SetValue(grid.SelectedObject,e.OldValue);grid.Refresh();MessageBox.Show(this,error.Message);}list.Refresh();};
   var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=82};bar.Controls.Add(new Label{Text="只接受独立观测；map坐标系、单位米/弧度和车体中心偏移须由驱动适配器对齐。",AutoSize=true,Width=800});var import=new Button{Text="导入硬件档案",AutoSize=true};import.Click+=(s,e)=>{using(var file=new OpenFileDialog{Filter="定位硬件档案|*.json"})if(file.ShowDialog(this)==DialogResult.OK)try{var info=new FileInfo(file.FileName);if(info.Length>65536)throw new Exception("硬件档案最大64KB。");CorrectionRules.Import(document,File.ReadAllText(file.FileName));RefreshList();}catch(Exception error){MessageBox.Show(this,error.Message);}};bar.Controls.Add(import);var remove=new Button{Text="删除选中源",AutoSize=true};remove.Click+=(s,e)=>{var source=list.SelectedItem as HardwareSource;if(source==null)return;if(document.Points.Any(p=>CorrectionRules.Items(p).Any(c=>c.SourceId==source.Id))){MessageBox.Show(this,"仍有纠错模板引用此源，请先删除相关模板。");return;}document.HardwareSources.Remove(source);RefreshList();};bar.Controls.Add(remove);bar.Controls.Add(new Button{Text="关闭",DialogResult=DialogResult.OK});Controls.Add(bar);RefreshList();}
  void RefreshList(){list.Items.Clear();foreach(var s in CorrectionRules.Sources(document))list.Items.Add(s);if(list.Items.Count>0)list.SelectedIndex=0;else grid.SelectedObject=null;}
 }
}
